    for (i in 0 until n) {
        if (f[i] == 1) {
            q.add(i)
            visited[i] = true
        }
    }

    // BFS to propagate reachability from assignment states
    while (q.isNotEmpty()) {
        val u = q.poll()
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true
                q.add(v)
            }
        }
    }

    // For each use state, perform reverse BFS to mark all states on paths to it
    val reverseAdj = Array(n) { mutableListOf<Int>() }
    for (u in 0 until n) {
        for (v in adj[u]) {
            reverseAdj[v].add(u)
        }
    }

    val marked = BooleanArray(n)
    val q2 = ArrayDeque<Int>()

    // Start from use states that are reachable from any assignment
