fun main() {
    val sc = FastScanner()
    val n = sc.nextInt()
    val m = sc.nextInt()
    val f = IntArray(n)
    for (i in 0 until n) {
        f[i] = sc.nextInt()
    }
    val adj = Array(n + 1) { mutableListOf<Int>() }
    val inDegree = IntArray(n + 1)
    for (_ in 0 until m) {
        val a = sc.nextInt()
        val b = sc.nextInt()
        adj[a].add(b)
        inDegree[b]++
    }

    val result = IntArray(n)
    val visited = BooleanArray(n + 1)
    val queue = ArrayDeque<Int>()

    // Initialize queue with nodes that have in-degree 0
    for (i in 1..n) {
        if (inDegree[i] == 0) {
            queue.add(i)
        }
    }

    while (queue.isNotEmpty()) {
        val u = queue.poll()
        if (visited[u]) continue
        visited[u] = true

        // Check if current node is an assignment (f[u-1] == 1)
        if (f[u - 1] == 1) {
            // BFS to find all reachable nodes from u without encountering another assignment
            val localVisited = BooleanArray(n + 1)
            val localQueue = ArrayDeque<Int>()
            localQueue.add(u)
            localVisited[u] = true

            while (localQueue.isNotEmpty()) {
                val v = localQueue.poll()
                result[v - 1] = 1

                for (w in adj[v]) {
                    if (!localVisited[w] && f[w - 1] != 1) {
                        localVisited[w] = true
                        localQueue.add(w)
                    }
                }
            }
        }

        // Process neighbors for topological sort
        for (v in adj[u]) {
            inDegree[v]--
            if (inDegree[v] == 0) {
                queue.add(v)
            }
        }
    }

    // Print the result
    for (r in result) {
        println(r)
    }
}

class FastScanner {
    private val br = java.io.BufferedReader(java.io.InputStreamReader(System.`in`))
    private var st: StringTokenizer? = null

    fun next(): String {
        while (st == null || !st!!.hasMoreElements()) {
            st = StringTokenizer(br.readLine())
        }
        return st!!.nextToken()
    }

    fun nextInt(): Int {
        return next().toInt()
    }
}
