        adj[a].add(b)
        revAdj[b].add(a)
    }

    val assign = f.mapIndexed { i, v -> if (v == 1) i else -1 }.filter { it != -1 }
    val use = f.mapIndexed { i, v -> if (v == 2) i else -1 }.filter { it != -1 }

    val reachableFromAssign = BooleanArray(n)
    val qAssign = ArrayDeque<Int>()
    for (a in assign) {
        if (!reachableFromAssign[a]) {
            reachableFromAssign[a] = true
            qAssign.add(a)
        }
    }
    while (qAssign.isNotEmpty()) {
        val u = qAssign.poll()
        for (v in adj[u]) {
            if (!reachableFromAssign[v]) {
                reachableFromAssign[v] = true
                qAssign.add(v)
            }
        }
    }

    val reachesUse = BooleanArray(n)
    val qUse = ArrayDeque<Int>()
    for (u in use) {
        if (!reachesUse[u]) {
            reachesUse[u] = true
            qUse.add(u)
        }
    }
    while (qUse.isNotEmpty()) {
        val u = qUse.poll()
