        val u = q.poll()
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true
                result[v] = 1
                q.add(v)
            }
        }
    }

    // Now, check if any use state (f[i] == 2) is reachable from any assignment state
    // If not, then all results should be 0
    val useReachable = BooleanArray(n)
    val q2 = ArrayDeque<Int>()
    val visited2 = BooleanArray(n)
    for (i in 0 until n) {
        if (f[i] == 1) {
            q2.add(i)
            visited2[i] = true
        }
    }

    while (q2.isNotEmpty()) {
        val u = q2.poll()
        for (v in adj[u]) {
            if (!visited2[v]) {
                visited2[v] = true
                if (f[v] == 2) {
                    useReachable[v] = true
                }
                q2.add(v)
            }
        }
    }

    // If no use state is reachable from any assignment state, output all 0s
