            dfs1(i, adj, visited, order)
        }
    }

    val visited2 = BooleanArray(n + 1)
    val comp = IntArray(n + 1)
    var label = 0
    for (i in order.asReversed()) {
        if (!visited2[i]) {
            label++
            dfs2(i, radj, visited2, comp, label)
        }
    }

    val compAssign = IntArray(label + 1) { 0 }
    val compUse = IntArray(label + 1) { 0 }
    for (i in 1..n) {
        val c = comp[i]
        if (f[i - 1] == 1) compAssign[c]++
        if (f[i - 1] == 2) compUse[c]++
    }

    val adjComp = Array(label + 1) { mutableSetOf<Int>() }
    for (u in 1..n) {
        for (v in adj[u]) {
            val cu = comp[u]
            val cv = comp[v]
            if (cu != cv) {
                adjComp[cu].add(cv)
            }
        }
    }

    val result = IntArray(n + 1) { 0 }
    for (i in 1..n) {
        val c = comp[i]
        if (compAssign[c] > 0 && compUse[c] > 0) {
            result[i] = 1
        } else {
            val reachable = bfs(c, adjComp, compAssign, compUse)
            if (reachable) {
                result[i] = 1
            }
        }
    }

