fun dfs1(u: Int, adj: Array<MutableList<Int>>, visited: BooleanArray, order: MutableList<Int>) {
    visited[u] = true
    for (v in adj[u]) {
        if (!visited[v]) {
            dfs1(v, adj, visited, order)
        }
    }
    order.add(u)
}

fun dfs2(u: Int, radj: Array<MutableList<Int>>, visited: BooleanArray, comp: IntArray, label: Int) {
    visited[u] = true
    comp[u] = label
    for (v in radj[u]) {
        if (!visited[v]) {
            dfs2(v, radj, visited, comp, label)
        }
    }
}

fun bfs(start: Int, adjComp: Array<MutableSet<Int>>, compAssign: IntArray, compUse: IntArray): Boolean {
    val visited = BooleanArray(adjComp.size)
    val q = ArrayDeque<Int>()
    q.add(start)
    visited[start] = true
    while (q.isNotEmpty()) {
        val u = q.poll()
        if (compAssign[u] > 0 && compUse[u] > 0) {
            return true
        }
        for (v in adjComp[u]) {
            if (!visited[v]) {
                visited[v] = true
                q.add(v)
            }
        }
    }
    return false
}
